                 bid = max(bid, max_yesterday_bid + 1)
        elif max_yesterday_bid < DAILY_SALARY * 0.5 and my_hp > 5 and max_water_units >= num_competitors:
            bid = min(bid, max_yesterday_bid + 10)

    final_bid = max(1.0, min(my_budget, bid))

    return final_bid

